PRAGMA foreign_keys = ON;
CREATE TABLE itineraries (id TEXT PRIMARY KEY NOT NULL CHECK(length(id) = 36 AND id = lower(id) AND substr(id,9,1) = '-' AND substr(id,14,1) = '-' AND substr(id,19,1) = '-' AND substr(id,24,1) = '-' AND length(replace(id,'-','')) = 32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*'), ownerId TEXT NOT NULL REFERENCES owners(id), title TEXT, city TEXT, days INTEGER NOT NULL CHECK(typeof(days) = 'integer' AND days >= 0), activities TEXT NOT NULL CHECK(json_valid(activities)), highlights TEXT CHECK(highlights IS NULL OR (json_valid(highlights) AND json_type(highlights) = 'array')), estimated_cost TEXT, subtitle TEXT, local_score REAL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), status TEXT, is_favorite INTEGER NOT NULL DEFAULT 0 CHECK(is_favorite IN (0,1)));
CREATE INDEX itineraries_owner_order ON itineraries(ownerId, created_at DESC, id DESC);
